<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {Refresh,Plus,View,User,Document,EditPen} from '@element-plus/icons-vue'
import {http,errorMessage} from '../lib/http'
import {useAuthStore} from '../stores/auth'
type Summary={pv:number;uv:number;posts:Record<string,number>;timezone:string;daily:{day:string;pv:number;uv:number}[]}
const data=ref<Summary|null>(null),loading=ref(true),error=ref(''),auth=useAuthStore()
const max=computed(()=>Math.max(1,...(data.value?.daily.map(day=>day.pv)||[])))
async function load(){loading.value=true;error.value='';try{data.value=(await http.get<Summary>('/analytics/summary')).data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
onMounted(()=>void load())
</script>
<template><section><div class="page-heading"><div><p class="section-kicker">OVERVIEW</p><h1>把今天，写成新的开始。</h1><p>文章与访问数据，一目了然。</p></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新数据</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><template v-else><div v-loading="loading" class="metric-grid"><el-card shadow="never"><div class="metric-top"><span>今日浏览 PV</span><el-icon><View/></el-icon></div><b>{{data?.pv??'—'}}</b><small>按 UTC 自然日统计</small></el-card><el-card shadow="never"><div class="metric-top"><span>今日访客 UV</span><el-icon><User/></el-icon></div><b>{{data?.uv??'—'}}</b><small>匿名访客去重</small></el-card><el-card shadow="never"><div class="metric-top"><span>已发布文章</span><el-icon><Document/></el-icon></div><b>{{data?.posts.published??0}}</b><small>在博客前台公开展示</small></el-card><el-card shadow="never"><div class="metric-top"><span>待完成草稿</span><el-icon><EditPen/></el-icon></div><b>{{data?.posts.draft??0}}</b><small>慢慢写，也很好</small></el-card></div><div class="dashboard-panels"><el-card shadow="never"><template #header><div class="card-heading"><span>最近 7 天的阅读</span><small>站内匿名统计 · UTC</small></div></template><div v-if="data?.daily.length" class="trend-chart"><div v-for="day in data.daily" :key="day.day" class="trend-day"><span>{{day.pv}}</span><div class="trend-track"><div :style="{height:`${Math.max(2,day.pv/max*100)}%`}" :title="`${day.day}：PV ${day.pv} / UV ${day.uv}`"></div></div><small>{{day.day.slice(5)}}</small></div></div><el-empty v-else description="还没有访问记录，分享一篇文章吧" :image-size="95"/></el-card><el-card shadow="never" class="quick-card"><p class="section-kicker">A NEW STORY</p><h2>想写的，<br/>就从现在开始。</h2><p>一个灵感、一段日常，<br/>都可以成为下一篇文章。</p><el-button v-if="auth.can('posts:write')" type="primary" :icon="Plus" @click="$router.push('/articles/new')">写一篇文章</el-button></el-card></div></template></section></template>
